custom_css:
/* Author: @jiuyi0204 | usage restrictions are recorded in project.config.json and the theme package. */

/* ===== src/tokens.css ===== */

/* Author: @jiuyi0204 | 霓虹夜刊 | 未经许可禁止二次修改、上传、转载或重新打包。 */
:root {
  --theme-surface: #101116;
  --theme-surface-muted: #191a20;
  --theme-surface-disabled: #282127;
  --theme-paper: #c6b7a0;
  --theme-paper-deep: #aa977f;
  --theme-paper-tint: rgba(70, 52, 47, 0.18);
  --theme-text-primary: #dfd2c2;
  --theme-text-secondary: #bfaea2;
  --theme-text-ink: #302927;
  --theme-text-disabled: #a8929e;
  --theme-border: #756159;
  --theme-border-soft: #493b40;
  --theme-accent: #a94c72;
  --theme-accent-strong: #cf648e;
  --theme-accent-dark: #612b42;
  --theme-silver: #b5a99f;
  --theme-focus-ring: #ef7cab;
  --theme-info: #567d8d;
  --theme-success: #66806c;
  --theme-warning: #a87840;
  --theme-error: #9f4858;
  --theme-opacity-disabled: 1;
  --theme-opacity-icon-muted: 0.76;
  --theme-opacity-code-copy: 0.72;
  --theme-code-overflow-x: auto;
  --theme-shadow: none;
  --theme-code-inline-surface: #594845;
  --theme-code-block-surface: #3b3132;
  --theme-code-text: #d4c3b3;
  --theme-code-muted: #a99591;
  --theme-code-accent: #c66c91;
  --theme-code-selection: #6b3a50;
  --theme-input-deck: #1a191f;
  --theme-input-surface: #272127;
  --theme-control-track: #8a706d;
  --theme-extension-header-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/8be87717892c3a46cdbed5cc10c7d6ee04914551/assets/%E9%9C%93%E8%99%B9%E5%A4%9C%E5%88%8A/lace-rail.webp");
  --ny-reset-none: none;
  --theme-paper-texture: linear-gradient(135deg, var(--theme-paper), var(--theme-paper-deep));
  --theme-night-texture: linear-gradient(145deg, var(--theme-surface), var(--theme-surface-muted));
  --theme-rose-texture: linear-gradient(135deg, var(--theme-accent-dark), var(--theme-accent));
  --ny-collage-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/594e1864905cc406b824ec78fd8ef5fce9637bb6/assets/%E9%9C%93%E8%99%B9%E5%A4%9C%E5%88%8A/night-collage.webp");
  --ny-paper-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/594e1864905cc406b824ec78fd8ef5fce9637bb6/assets/%E9%9C%93%E8%99%B9%E5%A4%9C%E5%88%8A/aged-paper.webp");
  --ny-jirai-bow-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/8be87717892c3a46cdbed5cc10c7d6ee04914551/assets/%E9%9C%93%E8%99%B9%E5%A4%9C%E5%88%8A/jirai-bow.webp");
  --ny-lace-check-image: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/8be87717892c3a46cdbed5cc10c7d6ee04914551/assets/%E9%9C%93%E8%99%B9%E5%A4%9C%E5%88%8A/lace-heart-check.webp");
  --ny-font-body: "Songti SC", STSong, SimSun, serif;
  --ny-topbar-height: 76px;
  --ny-input-height: 92px;
  --ny-control-size: 38px;
  --topBarBlockSize: var(--ny-topbar-height);
  --bottomFormBlockSize: var(--ny-input-height);
}

/* ===== src/kernel/protection.css ===== */

/* Author: @jiuyi0204 | 霓虹夜刊 | 交互保护层。 */
#top-settings-holder .drawer-toggle::before,
#send_form::before,
#chat .mes::before,
#chat .mes::after {
  pointer-events: none;
}

#top-settings-holder .drawer-toggle,
#send_form .menu_button,
#send_form #send_but,
#send_form #mes_stop,
#chat .mes_button,
#chat .menu_button {
  touch-action: manipulation;
}

#chat .mes_text,
#chat .mes_reasoning,
.drawer-content .scrollableInner,
.drawer-content textarea {
  overflow-wrap: anywhere;
}

/* ===== src/kernel/scrollbars.css ===== */

/* Author: @jiuyi0204 | 霓虹夜刊 | 只隐藏滚动条外观，保留全部滚动能力。 */
:where(
  html,
  body,
  #sheld,
  #sheld *,
  #chat,
  .drawer-content,
  .popup-content,
  .scrollable,
  .select2-results__options,
  #send_textarea,
  #chat .mes_text pre,
  #chat .mes_text .table-responsive
) {
  scrollbar-width: none;
  -ms-overflow-style: none;
}

:where(
  html,
  body,
  #sheld,
  #sheld *,
  #chat,
  .drawer-content,
  .popup-content,
  .scrollable,
  .select2-results__options,
  #send_textarea,
  #chat .mes_text pre,
  #chat .mes_text .table-responsive
)::-webkit-scrollbar {
  width: 0;
  height: 0;
}

/* ===== src/chat-layout.css ===== */

/* Author: @jiuyi0204 | 霓虹夜刊 | 22.5/55/22.5 黑胶夜刊主聊天。 */
body {
  background-color: var(--theme-surface);
  background-image: var(--theme-night-texture);
  color: var(--theme-text-primary);
  font-family: var(--ny-font-body);
}

#sheld {
  width: 55vw;
  max-width: none;
  margin-inline: auto;
  padding-top: 0;
  overflow: visible;
}

#chat {
  width: 100%;
  padding: 18px 12px calc(var(--ny-input-height) + 22px);
  background-color: var(--theme-surface);
  background-image: var(--theme-night-texture);
  border-right: 1px solid var(--theme-border-soft);
  border-left: 1px solid var(--theme-border-soft);
}

#chat .mes {
  position: relative;
  box-sizing: border-box;
  width: 100%;
  margin: 0 auto 18px;
}

#chat .mes[is_user="true"] {
  display: flex;
  align-items: center;
  min-height: 176px;
  padding: 28px 30px 28px 48px;
  background-color: var(--theme-surface-muted);
  background-image: var(--theme-night-texture);
  border: 1px solid var(--theme-border-soft);
  border-radius: 5px;
  overflow: visible;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper {
  position: absolute;
  z-index: 3;
  top: 8px;
  left: -19.5vw;
  flex: 0 0 auto;
  width: min(18vw, 300px);
  height: min(18vw, 300px);
  margin: 0;
  padding: 8px;
  background-color: var(--theme-surface);
  border: 1px solid var(--theme-silver);
  border-radius: 50%;
  box-sizing: border-box;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper::before,
#chat .mes[is_user="true"] > .mesAvatarWrapper::after {
  content: "";
  position: absolute;
  pointer-events: none;
  border-radius: 50%;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper::before {
  inset: -9px;
  border: 1px solid var(--theme-border);
  background: repeating-conic-gradient(from 8deg, var(--theme-border-soft) 0deg 4deg, transparent 4deg 9deg);
}

#chat .mes[is_user="true"] > .mesAvatarWrapper::after {
  inset: 4px;
  border: 1px solid var(--theme-accent-dark);
}

#chat .mes[is_user="true"] > .mesAvatarWrapper .avatar,
#chat .mes[is_user="true"] > .mesAvatarWrapper .avatar img {
  width: 100%;
  height: 100%;
  border-radius: 50%;
}

#chat .mes[is_user="true"] > .mesAvatarWrapper .avatar {
  position: relative;
  z-index: 1;
  overflow: hidden;
  border: 1px solid var(--theme-border-soft);
}

#chat .mes[is_user="true"] > .mesAvatarWrapper .avatar img {
  object-fit: cover;
}

#chat .mes[is_user="true"] > .mes_block {
  position: relative;
  z-index: 2;
  flex: 1 1 auto;
  min-width: 0;
  min-height: 116px;
}

#chat .mes[is_user="true"] > .mes_block::after {
  content: "";
  position: absolute;
  right: 0;
  bottom: 0;
  width: min(42%, 250px);
  height: 46px;
  background: repeating-linear-gradient(90deg, var(--theme-accent) 0 1px, transparent 1px 6px);
  clip-path: polygon(0 47%, 5% 30%, 10% 62%, 15% 20%, 20% 78%, 25% 34%, 30% 64%, 35% 14%, 40% 84%, 45% 39%, 50% 70%, 55% 25%, 60% 83%, 65% 43%, 70% 61%, 75% 17%, 80% 77%, 85% 35%, 90% 63%, 95% 39%, 100% 48%, 100% 52%, 95% 61%, 90% 37%, 85% 65%, 80% 23%, 75% 83%, 70% 39%, 65% 57%, 60% 17%, 55% 75%, 50% 30%, 45% 61%, 40% 16%, 35% 86%, 30% 36%, 25% 66%, 20% 22%, 15% 80%, 10% 38%, 5% 70%, 0 53%);
  pointer-events: none;
}

#chat .mes:not([is_user="true"]):not([is_system="true"]) {
  display: flex;
  align-items: stretch;
  padding: 38px clamp(34px, 4vw, 64px) 44px;
  background-color: var(--theme-paper);
  background-image: linear-gradient(var(--theme-paper-tint), var(--theme-paper-tint)), var(--ny-paper-image), var(--theme-paper-texture);
  background-repeat: no-repeat, repeat, no-repeat;
  background-size: cover, 512px 512px, cover;
  color: var(--theme-text-ink);
  text-shadow: none;
  border: 1px solid var(--theme-paper-deep);
  clip-path: polygon(0.7% 1.5%, 7% 0.5%, 14% 1.1%, 22% 0.4%, 31% 1.2%, 40% 0.4%, 51% 1.1%, 63% 0.5%, 75% 1.2%, 87% 0.4%, 99.2% 1.5%, 99.6% 13%, 99% 27%, 99.7% 42%, 99.1% 58%, 99.7% 74%, 99.2% 89%, 99.5% 98.2%, 90% 99.2%, 79% 98.5%, 67% 99.3%, 54% 98.6%, 42% 99.4%, 30% 98.7%, 17% 99.5%, 0.6% 98.4%, 1.1% 84%, 0.4% 69%, 1% 53%, 0.3% 38%, 1% 22%);
}

#chat .mes:not([is_user="true"]):not([is_system="true"]) > .mesAvatarWrapper {
  display: none;
}

#chat .mes:not([is_user="true"]):not([is_system="true"]) > .mes_block {
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
}

#chat .mes[is_system="true"] {
  padding: 12px 16px;
  background-color: var(--theme-surface-disabled);
  color: var(--theme-text-secondary);
  border-left: 3px solid var(--theme-accent);
}

#chat .ch_name {
  min-height: 38px;
  margin-bottom: 18px;
  border-bottom: 1px solid var(--theme-border-soft);
}

#chat .mes[is_user="true"] .name_text {
  color: var(--theme-accent-strong);
  font-family: var(--ny-font-body);
  font-size: 1.45em;
  font-weight: 400;
  letter-spacing: 0.08em;
}

#chat .mes:not([is_user="true"]):not([is_system="true"]) .name_text {
  color: var(--theme-accent-dark);
  font-family: "Songti SC", STSong, SimSun, serif;
  font-size: clamp(1.65em, 1.75vw, 2.15em);
  font-weight: 400;
  line-height: 1.08;
  letter-spacing: 0.06em;
}

#chat .timestamp,
#chat .mes_timer,
#chat .tokenCounterDisplay,
#chat .mesIDDisplay {
  color: var(--theme-text-secondary);
  font-size: 0.86em;
}

#chat .mes:not([is_user="true"]):not([is_system="true"]) .timestamp,
#chat .mes:not([is_user="true"]):not([is_system="true"]) .mes_timer,
#chat .mes:not([is_user="true"]):not([is_system="true"]) .tokenCounterDisplay,
#chat .mes:not([is_user="true"]):not([is_system="true"]) .mesIDDisplay {
  color: var(--theme-accent-dark);
}

#chat .swipe_left,
#chat .swipe_right,
#chat .swipes-counter {
  color: var(--theme-accent);
}

/* ===== src/full-text.css ===== */

/* Author: @jiuyi0204 | 霓虹夜刊 | 夜刊长文本与引文层级。 */
#chat .mes_text {
  max-width: 76ch;
  padding: 0;
  color: inherit;
  font-family: var(--ny-font-body);
  font-size: 1.1em;
  font-weight: 400;
  line-height: 1.9;
  letter-spacing: 0.035em;
}

#chat .mes[is_user="true"] .mes_text {
  max-width: 58ch;
  padding-right: min(31%, 190px);
  font-size: 1.14em;
  line-height: 1.75;
}

#chat .mes:not([is_user="true"]):not([is_system="true"]) .mes_text {
  width: min(96ch, 76%);
  max-width: 100%;
  margin-inline: auto;
}

#chat .mes:not([is_user="true"]):not([is_system="true"]) .mes_text q {
  color: var(--theme-accent-dark);
  opacity: 1;
  text-shadow: none;
}

#chat .mes[is_user="true"] .mes_text q {
  color: var(--theme-accent-strong);
  opacity: 1;
  text-shadow: none;
}

#chat .mes_text p {
  margin: 0 0 1em;
}

#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3 {
  color: var(--theme-accent-dark);
  font-family: var(--ny-font-body);
  font-weight: 400;
  letter-spacing: 0.08em;
}

#chat .mes_text blockquote {
  position: relative;
  max-width: 48%;
  margin: 1.6em 0 1.2em auto;
  padding: 0.7em 1.2em 0.7em 1.8em;
  color: var(--theme-accent-dark);
  border: 0;
  border-right: 2px solid var(--theme-accent);
  font-size: 1.18em;
  line-height: 1.55;
  text-align: right;
}

#chat .mes_text blockquote::before {
  content: "“";
  position: absolute;
  top: -0.3em;
  left: 0;
  color: var(--theme-accent);
  font-size: 2em;
}

#chat .mes_text hr {
  height: 18px;
  margin: 1.8em 0;
  background: repeating-linear-gradient(90deg, var(--theme-accent) 0 1px, transparent 1px 7px);
  border: 0;
  clip-path: polygon(0 47%, 8% 35%, 16% 64%, 24% 20%, 32% 77%, 40% 38%, 48% 69%, 56% 26%, 64% 80%, 72% 42%, 80% 67%, 88% 31%, 100% 49%, 100% 53%, 88% 69%, 80% 33%, 72% 58%, 64% 20%, 56% 74%, 48% 31%, 40% 62%, 32% 23%, 24% 80%, 16% 36%, 8% 65%, 0 53%);
}

#chat .mes_text :not(pre) > code {
  color: var(--theme-code-text);
  background-color: var(--theme-code-inline-surface);
  border: 1px solid var(--theme-border);
  text-shadow: none;
}

#chat .mes_text pre {
  color: var(--theme-code-text);
  background-color: var(--theme-code-block-surface);
  border: 1px solid var(--theme-border);
  box-shadow: none;
  padding: 14px;
  overflow-x: var(--theme-code-overflow-x);
  overflow-y: hidden;
}

#chat .mes_text pre code.hljs {
  color: var(--theme-code-text);
  background-color: var(--theme-code-block-surface);
  text-shadow: none;
}

#chat .mes_text pre code.hljs,
#chat .mes_text pre code.hljs .hljs-tag,
#chat .mes_text pre code.hljs .hljs-title,
#chat .mes_text pre code.hljs .hljs-name,
#chat .mes_text pre code.hljs .hljs-attribute {
  color: var(--theme-code-text);
  opacity: 1;
  text-shadow: none;
}

#chat .mes_text pre code.hljs .hljs-comment,
#chat .mes_text pre code.hljs .hljs-punctuation,
#chat .mes_text pre code.hljs .hljs-operator,
#chat .mes_text pre code.hljs .hljs-subst,
#chat .mes_text pre code.hljs .hljs-meta {
  color: var(--theme-code-muted);
  opacity: 1;
  text-shadow: none;
}

#chat .mes_text pre code.hljs .hljs-keyword,
#chat .mes_text pre code.hljs .hljs-string,
#chat .mes_text pre code.hljs .hljs-number,
#chat .mes_text pre code.hljs .hljs-literal,
#chat .mes_text pre code.hljs .hljs-built_in,
#chat .mes_text pre code.hljs .hljs-variable,
#chat .mes_text pre code.hljs .hljs-selector-tag,
#chat .mes_text pre code.hljs .hljs-section {
  color: var(--theme-code-accent);
  opacity: 1;
  text-shadow: none;
}

#chat .mes_text pre code.hljs::selection,
#chat .mes_text pre code.hljs *::selection {
  color: var(--theme-code-text);
  background-color: var(--theme-code-selection);
}

#chat .mes:not([is_user="true"]):not([is_system="true"]) .mes_text .code-copy {
  color: var(--theme-accent);
  opacity: var(--theme-opacity-code-copy);
  filter: none;
  text-shadow: none;
}

#chat .mes:not([is_user="true"]):not([is_system="true"]) .mes_text .code-copy:hover {
  color: var(--theme-accent-strong);
  opacity: 1;
}

#chat .mes_text a {
  color: var(--theme-accent-strong);
  text-decoration-color: var(--theme-accent);
}

#chat .mes_text img,
#chat .mes_text video {
  max-width: 100%;
  border: 1px solid var(--theme-border);
}

/* ===== src/windows/stage.css ===== */

/* Author: @jiuyi0204 | 霓虹夜刊 | 桌面左侧持续拼贴与真实User头像舞台。 */
@media screen and (min-width: 1001px) {
  body::before {
    content: "";
    position: fixed;
    z-index: 20;
    top: var(--topBarBlockSize);
    bottom: var(--bottomFormBlockSize);
    left: 0;
    width: 22.5vw;
    background-image: var(--ny-collage-image);
    background-repeat: no-repeat;
    background-position: left center;
    background-size: contain;
    pointer-events: none;
  }

  body::after {
    content: "";
    position: fixed;
    z-index: 21;
    top: calc(var(--topBarBlockSize) + 28px);
    left: 3vw;
    width: min(18vw, 300px);
    aspect-ratio: 1;
    box-sizing: border-box;
    background-color: var(--theme-surface);
    border: 1px solid var(--theme-silver);
    border-radius: 50%;
    outline: 1px solid var(--theme-border);
    outline-offset: 8px;
    pointer-events: none;
  }

  #chat > .mes[is_user="true"].last_mes > .mesAvatarWrapper,
  #chat > .mes[is_user="true"]:nth-last-child(2) > .mesAvatarWrapper {
    position: fixed;
    z-index: 35;
    top: calc(var(--topBarBlockSize) + 28px);
    left: 3vw;
  }
}

/* ===== src/windows/topbar.css ===== */

/* Author: @jiuyi0204 | 霓虹夜刊 | 物件式九入口。 */
#top-bar {
  height: var(--topBarBlockSize);
}

#top-settings-holder {
  height: var(--topBarBlockSize);
  min-height: var(--topBarBlockSize);
  padding: 9px 10px;
  background-color: var(--theme-surface);
  border-bottom: 1px solid var(--theme-border-soft);
}

#top-settings-holder > .drawer {
  flex: 1 1 0;
  width: auto;
  min-width: 0;
}

#top-settings-holder .drawer-toggle {
  min-height: 54px;
  padding: 7px 8px;
  color: var(--theme-text-primary);
  background-color: var(--theme-surface);
  border: 0;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 5px;
}

#top-settings-holder .drawer-content.openDrawer:not(.fillLeft):not(.fillRight) {
  top: var(--topBarBlockSize);
  max-height: calc(100dvh - var(--topBarBlockSize) - var(--bottomFormBlockSize));
}

#top-settings-holder .drawer-toggle:hover,
#top-settings-holder .drawer-toggle.openDrawer {
  color: var(--theme-accent-strong);
  background-color: var(--theme-surface-muted);
}

#top-settings-holder .drawer-icon {
  padding: 0;
  color: inherit;
  font-size: 0;
  opacity: 1;
  filter: none;
  text-shadow: none;
}

#top-settings-holder .drawer-icon::before {
  display: block;
  font-family: Georgia, serif;
  font-size: 23px;
  font-weight: 400;
  line-height: 1;
}

#ai-config-button .drawer-icon::before { content: "◉"; }
#sys-settings-button .drawer-icon::before { content: "⌁"; }
#advanced-formatting-button .drawer-icon::before { content: "♥"; }
#WI-SP-button .drawer-icon::before { content: "▥"; }
#user-settings-button .drawer-icon::before { content: "★"; }
#backgrounds-button .drawer-icon::before { content: "▤"; }
#extensions-settings-button .drawer-icon::before {
  content: "✿";
  font-family: Georgia, "Times New Roman", serif;
  font-size: 21px;
  font-weight: 400;
}
#persona-management-button .drawer-icon::before { content: "♢"; }
#rightNavHolder .drawer-icon::before {
  content: "";
  width: 23px;
  height: 16px;
  background-image: var(--ny-jirai-bow-image);
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  pointer-events: none;
}

#advanced-formatting-button .drawer-icon,
#extensions-settings-button .drawer-icon,
#rightNavHolder .drawer-icon {
  color: var(--theme-accent-strong);
}

#top-settings-holder .drawer-toggle::after {
  display: block;
  color: inherit;
  font-family: var(--ny-font-body);
  font-size: 10px;
  font-weight: 400;
  line-height: 1;
  letter-spacing: 0.05em;
  white-space: nowrap;
}

#ai-config-button .drawer-toggle::after { content: "回复配置"; }
#sys-settings-button .drawer-toggle::after { content: "API"; }
#advanced-formatting-button .drawer-toggle::after { content: "聊天设置"; }
#WI-SP-button .drawer-toggle::after { content: "世界书"; }
#user-settings-button .drawer-toggle::after { content: "用户"; }
#backgrounds-button .drawer-toggle::after { content: "背景"; }
#extensions-settings-button .drawer-toggle::after { content: "插件扩展"; }
#persona-management-button .drawer-toggle::after { content: "身份"; }
#rightNavHolder .drawer-toggle::after { content: "角色设置"; }

#top-settings-holder .drawer-toggle:focus-visible {
  outline: 2px solid var(--theme-focus-ring);
  outline-offset: 2px;
}

/* ===== src/windows/panels.css ===== */

/* Author: @jiuyi0204 | 霓虹夜刊 | 全窗口统一编辑部材质。 */
#left-nav-panel,
#rm_api_block,
#AdvancedFormatting,
#WorldInfo,
#user-settings-block,
#Backgrounds,
#rm_extensions_block,
#PersonaManagement,
