  background-color: var(--theme-input-deck);
}

#send_form #nonQRFormItems {
  min-height: 62px;
  box-sizing: border-box;
  gap: 10px;
}

#send_textarea {
  min-height: 56px;
  max-height: 150px;
  padding: 15px 17px;
  color: var(--theme-text-primary);
  caret-color: var(--theme-accent-strong);
  background-color: var(--theme-input-surface);
  border: 1px solid var(--theme-border);
  border-radius: 4px;
  font-family: var(--ny-font-body);
  font-size: 1.08em;
  line-height: 1.55;
}

#send_textarea::placeholder {
  color: var(--theme-text-secondary);
}

#send_form #leftSendForm,
#send_form #rightSendForm {
  position: relative;
  gap: 8px;
}

#send_form #options_button,
#send_form #extensionsMenuButton,
#send_form #send_but,
#send_form #mes_stop,
#send_form .stscript_btn,
#send_form #mes_continue,
#send_form #mes_impersonate {
  width: 52px;
  height: 52px;
  color: var(--theme-text-primary);
  background-color: var(--theme-input-surface);
  border: 1px solid var(--theme-border);
  border-radius: 4px;
  line-height: 52px;
  text-align: center;
}

#send_form #options_button::before,
#send_form #extensionsMenuButton::before,
#send_form #send_but::before,
#send_form #mes_stop::before {
  display: block;
  font-family: Georgia, serif;
  font-size: 22px;
}

#send_form #options_button,
#send_form #extensionsMenuButton,
#send_form #send_but,
#send_form #mes_stop {
  font-size: 0;
}

#send_form #options_button::before { content: "▤"; }
#send_form #extensionsMenuButton::before { content: "✦"; }
#send_form #send_but::before { content: "➤"; }
#send_form #mes_stop::before { content: "■"; }
#send_form #mes_stop i { display: none; }

#send_form #leftSendForm::after {
  content: "魔法";
  position: absolute;
  right: 0;
  bottom: -10px;
  left: 0;
  color: var(--theme-text-secondary);
  font-family: var(--ny-font-body);
  font-size: 9px;
  line-height: 1;
  text-align: center;
  pointer-events: none;
}

#send_form #send_but {
  color: var(--theme-text-primary);
  background-color: var(--theme-accent-dark);
  border-color: var(--theme-accent);
}

#send_form #options_button:hover,
#send_form #extensionsMenuButton:hover,
#send_form #send_but:hover,
#send_form #mes_stop:hover,
#send_form .stscript_btn:hover,
#send_form #mes_continue:hover,
#send_form #mes_impersonate:hover {
  color: var(--theme-accent-strong);
  border-color: var(--theme-accent);
}

#send_textarea:focus-visible,
#send_form #options_button:focus-visible,
#send_form #extensionsMenuButton:focus-visible,
#send_form #send_but:focus-visible,
#send_form #mes_stop:focus-visible,
#send_form .stscript_btn:focus-visible,
#send_form #mes_continue:focus-visible,
#send_form #mes_impersonate:focus-visible {
  outline: 2px solid var(--theme-focus-ring);
  outline-offset: 2px;
}

#send_form.no-connection #send_textarea {
  color: var(--theme-text-disabled);
  background-color: var(--theme-surface-disabled);
}

#send_form.no-connection #send_but,
body[data-generating="true"] #send_form #send_but {
  color: var(--theme-text-disabled);
  background-color: var(--theme-surface-disabled);
  border-color: var(--theme-border-soft);
}

body[data-generating="true"] #send_form #mes_stop {
  color: var(--theme-text-primary);
  background-color: var(--theme-accent-dark);
  border-color: var(--theme-accent);
}

