/* ===== src/windows/states.css ===== */

/* Author: @jiuyi0204 | 霓虹夜刊 | v5 视觉状态合同实现。 */
.mes_reasoning_details {
  color: var(--theme-text-secondary);
  background-color: var(--theme-surface-muted);
  border: 1px solid var(--theme-border-soft);
}

.mes_reasoning_details:not([open]) { background-color: var(--theme-surface); }
.mes_reasoning_details[open] { background-color: var(--theme-surface-muted); }
.mes_reasoning_details[data-reasoning-state="thinking"] { border-color: var(--theme-accent); }
.mes_reasoning_details[data-reasoning-state="done"] { border-color: var(--theme-success); }
.mes_reasoning_details > summary:focus-visible { outline: 2px solid var(--theme-focus-ring); }
.mes_reasoning_details .mes_reasoning { color: var(--theme-text-secondary); }
.mes_reasoning_details .mes_reasoning_arrow { color: var(--theme-accent); }

#completion_prompt_manager {
  color: var(--theme-text-primary);
  background-color: var(--theme-surface);
}

#completion_prompt_manager .completion_prompt_manager_prompt {
  color: var(--theme-text-primary);
  background-color: var(--theme-surface-muted);
  border: 1px solid var(--theme-border-soft);
  opacity: 1;
  filter: none;
  text-shadow: none;
}

#completion_prompt_manager .completion_prompt_manager_prompt_disabled {
  color: var(--theme-text-disabled);
  background-color: var(--theme-surface-disabled);
  border-color: var(--theme-border-soft);
  filter: none;
  opacity: var(--theme-opacity-disabled);
  text-shadow: none;
}

#completion_prompt_manager .completion_prompt_manager_prompt:not(.completion_prompt_manager_prompt_disabled) {
  color: var(--theme-text-primary);
  background-color: var(--theme-surface-muted);
  border-color: var(--theme-accent);
  opacity: 1;
  filter: none;
  text-shadow: none;
}

#completion_prompt_manager .completion_prompt_manager_prompt.completion_prompt_manager_prompt_disabled {
  color: var(--theme-text-disabled);
  background-color: var(--theme-surface-disabled);
  border-color: var(--theme-border-soft);
  opacity: var(--theme-opacity-disabled);
  filter: none;
  text-shadow: none;
}

#completion_prompt_manager .completion_prompt_manager_prompt:hover {
