input[type="checkbox"] {
  -webkit-appearance: none;
  appearance: none;
  width: 1.55em;
  height: 1.55em;
  color: var(--theme-accent);
  background-color: var(--theme-surface);
  border: 1px solid var(--theme-border);
  background-image: var(--ny-reset-none);
  background-repeat: no-repeat;
  background-position: center;
  background-size: contain;
  border-radius: 7px;
  box-shadow: none;
  filter: none;
}

input[type="checkbox"]::before {
  content: "";
  width: 0;
  height: 0;
  background-color: transparent;
  clip-path: var(--ny-reset-none);
  transform: var(--ny-reset-none);
  box-shadow: none;
}

input[type="checkbox"]:checked {
  color: var(--theme-accent-strong);
  background-color: transparent;
  background-image: var(--ny-lace-check-image);
  border-color: transparent;
}

input[type="checkbox"]:checked::before {
  background-color: transparent;
  transform: var(--ny-reset-none);
}

input[type="checkbox"]:disabled {
  color: var(--theme-text-disabled);
  background-color: var(--theme-surface-disabled);
  border-color: var(--theme-border-soft);
  opacity: var(--theme-opacity-disabled);
  filter: none;
}

input[type="checkbox"]:disabled::before {
  background-color: var(--theme-text-disabled);
}

input[type="checkbox"]:focus-visible {
  outline: 2px solid var(--theme-focus-ring);
  outline-offset: 2px;
}

input[type="radio"] {
  -webkit-appearance: none;
  appearance: none;
  width: 1.25em;
  height: 1.25em;
  background-color: var(--theme-surface);
  border: 2px solid var(--theme-border);
  border-radius: 50%;
  box-shadow: inset 0 0 0 3px var(--theme-surface), inset 0 0 0 5px var(--theme-border-soft);
  filter: none;
}

input[type="radio"]:checked {
  background-color: var(--theme-accent);
  border-color: var(--theme-accent-strong);
  box-shadow: inset 0 0 0 3px var(--theme-surface), inset 0 0 0 5px var(--theme-border);
}

input[type="radio"]:disabled {
  background-color: var(--theme-surface-disabled);
  border-color: var(--theme-border-soft);
  box-shadow: none;
  opacity: var(--theme-opacity-disabled);
  filter: none;
}

input[type="radio"]:focus-visible {
  outline: 2px solid var(--theme-focus-ring);
  outline-offset: 2px;
}

.checkbox_label {
  color: var(--theme-text-primary);
  opacity: 1;
  filter: none;
  text-shadow: none;
}

input[type="range"] {
  -webkit-appearance: none;
  appearance: none;
  height: 7px;
  background: var(--theme-control-track);
  border: 1px solid var(--theme-border);
  border-radius: 999px;
  box-shadow: none;
  filter: none;
}

input[type="range"]::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 22px;
  height: 22px;
  background: var(--theme-accent);
  border: 2px solid var(--theme-border);
  border-radius: 50%;
  box-shadow: inset 0 0 0 3px var(--theme-surface), inset 0 0 0 5px var(--theme-border-soft);
  filter: none;
}

input[type="range"]::-moz-range-thumb {
  width: 18px;
  height: 18px;
  background: var(--theme-accent);
  border: 2px solid var(--theme-border);
  border-radius: 50%;
  box-shadow: inset 0 0 0 3px var(--theme-surface), inset 0 0 0 5px var(--theme-border-soft);
  filter: none;
}

input[type="range"]:disabled {
  background: var(--theme-border-soft);
  border-color: var(--theme-border-soft);
  box-shadow: none;
  opacity: var(--theme-opacity-disabled);
  filter: none;
}

input[type="range"]:disabled::-webkit-slider-thumb {
  background: var(--theme-text-disabled);
  border-color: var(--theme-border-soft);
  box-shadow: inset 0 0 0 3px var(--theme-surface-disabled);
  filter: none;
}

input[type="range"]:disabled::-moz-range-thumb {
  background: var(--theme-text-disabled);
  border-color: var(--theme-border-soft);
  box-shadow: inset 0 0 0 3px var(--theme-surface-disabled);
  filter: none;
}

input[type="range"]:focus-visible {
  outline: 2px solid var(--theme-focus-ring);
  outline-offset: 4px;
}

.inline-drawer-header,
.standoutHeader {
  color: var(--theme-text-primary);
