  #send_textarea {
    grid-column: 2;
    grid-row: 1;
    order: 0;
    width: 100%;
    min-width: 0;
    min-height: 38px;
    height: auto;
    max-height: 76px;
    padding: 7px 8px;
    font-size: 14px;
    line-height: 1.3;
    field-sizing: fixed;
    resize: none;
  }

  #send_textarea::placeholder {
    color: var(--theme-text-secondary) !important;
    overflow: hidden;
    font-size: 13px;
    text-align: left;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  #send_form #leftSendForm,
  #send_form #rightSendForm {
    order: 0;
    flex: none;
    width: max-content;
    min-width: 0;
    max-width: 76px;
    height: auto;
    flex-wrap: nowrap;
    overflow-x: auto;
    overflow-y: visible;
  }

  #send_form #leftSendForm {
    grid-column: 1;
    grid-row: 1;
  }

  #send_form #rightSendForm {
    grid-column: 3;
    grid-row: 1;
  }

  #send_form #leftSendForm::after {
    display: none;
  }

  #send_form #options_button,
  #send_form #extensionsMenuButton,
  #send_form #send_but,
  #send_form #mes_stop,
  #send_form .stscript_btn,
  #send_form #mes_continue,
  #send_form #mes_impersonate {
    flex: 0 0 36px;
    width: 36px;
    height: 36px;
    line-height: 36px;
  }

  #send_form #leftSendForm > div,
  #send_form #rightSendForm > div {
    flex-basis: 36px;
    width: 36px;
    height: 36px;
    max-width: 36px;
    max-height: 36px;
    box-sizing: border-box;
  }

  #right-nav-panel #avatar_div {
    grid-template-columns: 74px minmax(0, 1fr);
    gap: 10px;
  }

  #right-nav-panel #avatar_div_div {
    width: 74px;
    height: 74px;
    flex-basis: 74px;
  }

  #rm_extensions_block {
    padding-inline: 6px;
  }

  #rm_extensions_block #extensions_settings,
  #rm_extensions_block #extensions_settings2 {
    padding: 12px 6px 6px;
    background-color: var(--theme-surface-muted);
    background-image: var(--theme-extension-header-image);
    background-repeat: repeat-x;
    background-position: left top;
    background-size: auto 7px;
    border: 1px solid var(--theme-border-soft);
    border-radius: 7px;
    box-sizing: border-box;
  }

  #rm_extensions_block #extensions_settings .inline-drawer-header,
  #rm_extensions_block #extensions_settings2 .inline-drawer-header {
    min-height: 38px;
    margin: 0;
    padding: 7px 9px;
    color: var(--theme-text-primary);
    background-color: transparent;
    background-image: none;
    border: 0;
    border-bottom: 1px solid var(--theme-border-soft);
    border-radius: 0;
    box-shadow: none;
    font-family: var(--ny-font-body);
    font-size: 0.92em;
    font-weight: 600;
  }

  #rm_extensions_block #extensions_settings > .inline-drawer:nth-child(even) > .inline-drawer-header,
  #rm_extensions_block #extensions_settings2 > .inline-drawer:nth-child(even) > .inline-drawer-header,
  #rm_extensions_block #extensions_settings > .extension_container > .inline-drawer:nth-child(even) > .inline-drawer-header,
  #rm_extensions_block #extensions_settings2 > .extension_container > .inline-drawer:nth-child(even) > .inline-drawer-header {
    background-color: color-mix(in srgb, var(--theme-surface) 54%, transparent);
  }

  #rm_extensions_block #extensions_settings .inline-drawer-header .inline-drawer-icon,
  #rm_extensions_block #extensions_settings2 .inline-drawer-header .inline-drawer-icon {
    flex: 0 0 20px;
    width: 20px;
    height: 20px;
    color: var(--theme-accent);
    background-color: transparent;
    border: 0;
    border-radius: 0;
    box-shadow: none;
    font-size: 14px;
  }

  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel {
    width: 100%;
    max-width: 100%;
  }
}

/* ===== src/fallback.css ===== */

/* Author: @jiuyi0204 | 霓虹夜刊 | 无图片和字体资源时的安全回退。 */
@supports not (background-image: linear-gradient(#000, #fff)) {
  body,
  #chat {
    background-image: none;
  }

  #chat .mes:not([is_user="true"]):not([is_system="true"]) {
    background-image: none;
  }
}

@supports not (font-family: "Songti SC") {
  body,
  #chat .mes_text,
  #chat .name_text {
    font-family: SimSun, serif;
  }
}
